def add_transaction(account, amount):
    """Add a transaction to the account."""
    account[str(len(account) + 1)] = amount

def remove_transaction(account, transaction_id):
    """Remove a transaction from the account."""
    if transaction_id in account:
        del account[transaction_id]

def get_balance(account):
    """Calculate the current balance of the account."""
    total = 0
    for transaction in account.values():
        total += transaction
    return total

def manage_account():
    """Manage the person's finances."""
    account = {}

    while True:
        print("Welcome to the finance manager!")
        print("Available actions:")
        print("  - add transaction <amount>")
        print("  - remove transaction <transaction_id>")
        print("  - get balance")
        print("  - exit")

