        if action == "exit":
            break

        elif action.startswith("add transaction"):
            amount = float(action.split(" ")[2])
            add_transaction(account, amount)

        elif action.startswith("remove transaction"):
            transaction_id = int(action.split(" ")[2])
            remove_transaction(account, transaction_id)

        elif action == "get balance":
            balance = get_balance(account)
            print(f"Your balance is ${balance:.2f}.")

        else:
            print("Invalid action. Please try again.")

